-- 4. INSERT INTO — massa de dados FICTÍCIA
-- Volumes (justificativa no README, seção 4): 90 distribuidores, 99 produtos, ~490 pedidos/mês
-- (set e out/2026), ~50 compras/mês (ago a out/2026). Pedidos de 01/09 a 02/11/2026.
-- 2 marcas e 9 funcionários (equipe real em número; nomes fictícios); 18 pedidos cancelados;
-- 25 devoluções; parcelas de contas a pagar para todas as compras.
-- Variedade intencional: pedidos pendentes, liberados, entregues e cancelados; pagamento à vista, parcelado,
-- por acordo (com saldo em aberto); produtos abaixo do mínimo, sem lote e nunca pedidos;
-- lotes vencidos com saldo, de validade crítica (< 30 dias) e a vencer em até 90 dias;
-- fornecedor sem compras; reajuste de preços em 01/10/2026 (preço praticado x preço vigente).
-- Ordem: tabelas referenciadas primeiro, para respeitar as chaves estrangeiras.
-- =====================================================================

